using System;
using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace Underwater.Editor {
public static class ReefCreaturePolish {
 public static void Run(){Apply();Validate();}
 const string Scene="Assets/Scenes/Underwater_Realistic.unity";
 public static void Inspect(){
  var p="Assets/UnderwaterArt/LicensedStingray/Stingray.fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(p);importer.animationType=ModelImporterAnimationType.Legacy;importer.importAnimation=true;importer.isReadable=true;var clips=importer.defaultClipAnimations;foreach(var c in clips){c.loopTime=true;c.wrapMode=WrapMode.Loop;}importer.clipAnimations=clips;importer.SaveAndReimport();
  foreach(var a in AssetDatabase.LoadAllAssetsAtPath(p)){if(a is Mesh m)Debug.Log("IMPORTED_RAY mesh="+m.name+" vertices="+m.vertexCount+" bounds="+m.bounds);if(a is AnimationClip c)Debug.Log("IMPORTED_RAY clip="+c.name+" duration="+c.length);}
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(p);foreach(var t in prefab.GetComponentsInChildren<Transform>())Debug.Log("IMPORTED_RAY node="+t.name+" p="+t.localPosition+" s="+t.localScale+" rotation="+t.localEulerAngles);
 }
 public static void Apply(){
  Inspect();var scene=EditorSceneManager.OpenScene(Scene);
  InstallRays();InstallOctopus();RebuildWreckFish();InstallGrouper();
  foreach(var life in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None))if(life.kind=="Lumen"&&!life.GetComponent<ReefFishFollower>())life.gameObject.AddComponent<ReefFishFollower>();
  var sound=UnityEngine.Object.FindFirstObjectByType<ReefSoundscape>();if(sound&&!sound.GetComponent<CreatureProximityAudio>())sound.gameObject.AddComponent<CreatureProximityAudio>();
  BakeDolphin();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();ReefRealismPass.Apply();Debug.Log("CREATURE_POLISH_SAVED");
 }
 [Serializable] class GrouperData{public GrouperPart[] parts;}
 [Serializable] class GrouperPart{public Vector3[] vertices,normals;public int[] indices;public Color color;}
 static void InstallGrouper(){var data=JsonUtility.FromJson<GrouperData>(File.ReadAllText("Assets/UnderwaterArt/LicensedGrouper/GrouperGeometry.json"));var vertices=new System.Collections.Generic.List<Vector3>();var normals=new System.Collections.Generic.List<Vector3>();var colors=new System.Collections.Generic.List<Color>();var indices=new System.Collections.Generic.List<int>();foreach(var part in data.parts){int offset=vertices.Count;vertices.AddRange(part.vertices);normals.AddRange(part.normals);foreach(var v in part.vertices)colors.Add(part.color);foreach(int i in part.indices)indices.Add(i+offset);}var mesh=new Mesh{name="Quaternius coral grouper"};mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetColors(colors);mesh.SetTriangles(indices,0);mesh.uv=new Vector2[vertices.Count];mesh.RecalculateBounds();var bounds=mesh.bounds;bounds.Expand(.15f);mesh.bounds=bounds;
  var saved=Save(mesh,"QuaterniusGrouper");foreach(var actor in UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None))if(actor.species==WreckCreature.Species.Grouper){actor.GetComponent<MeshFilter>().sharedMesh=saved;foreach(string name in new[]{"Grouper pupils","Grouper mouth"}){var detail=actor.transform.Find(name);if(detail)UnityEngine.Object.DestroyImmediate(detail.gameObject);}string path="Assets/UnderwaterArt/LicensedGrouper/GrouperSkin.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Underwater/Wreck Creature Skin"));AssetDatabase.CreateAsset(mat,path);}mat.SetFloat("_VertexColors",1);mat.SetFloat("_Kind",0);actor.GetComponent<Renderer>().sharedMaterial=mat;EditorUtility.SetDirty(mat);}Debug.Log("GROUPER_IMPORTED triangles="+indices.Count/3+" vertices="+vertices.Count+" bounds="+bounds);
 }
 static void InstallOctopus(){var actor=Array.Find(UnityEngine.Object.FindObjectsByType<ReefEncounter>(FindObjectsSortMode.None),a=>a.response==ReefEncounter.Response.Octopus);if(!actor)return;foreach(var r in actor.GetComponentsInChildren<Renderer>())if(r.transform.parent==actor.transform||r.name=="Tapered arm")r.enabled=false;var old=actor.transform.Find("Detailed octopus");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);
  var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UnderwaterArt/LicensedOctopus/Octopus.fbx"));model.name="Detailed octopus";model.transform.SetParent(actor.transform,false);model.transform.localScale=Vector3.one*.5f;model.transform.localPosition=Vector3.down*.085f;
  string path="Assets/UnderwaterArt/LicensedOctopus/OctopusSkin.mat";var skin=AssetDatabase.LoadAssetAtPath<Material>(path);if(!skin){skin=new Material(Shader.Find("Underwater/Octopus Skin"));AssetDatabase.CreateAsset(skin,path);}skin.color=new Color(.55f,.33f,.18f);skin.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/UnderwaterArt/LicensedOctopus/low-poly-octopus_palette.png");skin.SetFloat("_Imported",1);foreach(var r in model.GetComponentsInChildren<Renderer>())r.sharedMaterial=skin;actor.skin=model.GetComponentsInChildren<Renderer>();actor.tentacles=Array.Empty<Transform>();EditorUtility.SetDirty(actor);EditorUtility.SetDirty(skin);
 }
 static Mesh Save(Mesh mesh,string name){string folder="Assets/UnderwaterArt/CreaturePolish";Directory.CreateDirectory(folder);AssetDatabase.Refresh();string path=folder+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=mesh.vertices;old.triangles=mesh.triangles;old.normals=mesh.normals;old.uv=mesh.uv;old.colors=mesh.colors;old.bounds=mesh.bounds;EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static void Detail(Transform parent,string name,Mesh mesh,Color color){var previous=parent.Find(name);if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);string path="Assets/UnderwaterArt/CreaturePolish/"+name+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(!material){material=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(material,path);}material.color=color;material.SetFloat("_Glossiness",.45f);var child=new GameObject(name);child.transform.SetParent(parent,false);child.AddComponent<MeshFilter>().sharedMesh=Save(mesh,name);child.AddComponent<MeshRenderer>().sharedMaterial=material;}
 static void RebuildWreckFish(){foreach(var actor in UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None)){
  if(actor.species==WreckCreature.Species.Moray){var g=new ReefGeometry();var p=new Vector3[30];var radius=new float[30];for(int i=0;i<p.Length;i++){float t=i/29f;p[i]=new Vector3(Mathf.Sin(t*5)*.1f,Mathf.Sin(t*Mathf.PI)*-.05f,Mathf.Lerp(-1.65f,.4f,t));radius[i]=Mathf.Lerp(.012f,.145f,Mathf.Pow(t,.6f));}g.Tube(p,radius,16,Color.white);g.Ellipsoid(new Vector3(0,.09f,.48f),new Vector3(.15f,.105f,.29f),12,18);for(int i=0;i<27;i++){int k=Mathf.Min(i+1,p.Length-2);var b=p[k]+Vector3.up*radius[k]*.85f;var c=p[k+1]+Vector3.up*radius[k+1]*.85f;int a=g.Vertex(b,Vector2.zero,Color.white);g.Vertex(b+Vector3.up*.06f,Vector2.up,Color.white);g.Vertex(c+Vector3.up*.06f,Vector2.one,Color.white);g.Vertex(c,Vector2.right,Color.white);g.Quad(a,a+1,a+2,a+3);}actor.GetComponent<MeshFilter>().sharedMesh=Save(g.Mesh("Tapered moray and continuous dorsal fin"),"MorayAnatomy");}
 }}
 static void InstallRays(){
  string folder="Assets/UnderwaterArt/LicensedStingray/";var material=AssetDatabase.LoadAssetAtPath<Material>(folder+"RaySkin.mat");if(!material){material=new Material(Shader.Find("Underwater/Rigged Ray Skin"));AssetDatabase.CreateAsset(material,folder+"RaySkin.mat");}material.shader=Shader.Find("Underwater/Rigged Ray Skin");material.color=new Color(.38f,.35f,.26f);material.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(folder+"Stingray.png");material.SetFloat("_Glossiness",.22f);EditorUtility.SetDirty(material);
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(folder+"Stingray.fbx");AnimationClip swim=null;foreach(var a in AssetDatabase.LoadAllAssetsAtPath(folder+"Stingray.fbx"))if(a is AnimationClip c&&!c.name.StartsWith("__"))swim=c;
  foreach(var ray in UnityEngine.Object.FindObjectsByType<StingraySwimmer>(FindObjectsSortMode.None)){
   var previous=ray.transform.Find("Rigged stingray");if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);
   var model=(GameObject)PrefabUtility.InstantiatePrefab(prefab);model.name="Rigged stingray";model.transform.SetParent(ray.transform,false);model.transform.localScale=Vector3.one*.13f;
   foreach(var skin in model.GetComponentsInChildren<Renderer>())skin.sharedMaterial=material;
   var motion=model.AddComponent<ReefImportedAnimation>();motion.tailWarning=ray.transform.Find("Tail-only caution zone");foreach(var t in model.GetComponentsInChildren<Transform>())if(t.name=="Bone.003")motion.tailBone=t;
   var eyeMaterial=AssetDatabase.LoadAssetAtPath<Material>(folder+"RayEyes.mat");if(!eyeMaterial){eyeMaterial=new Material(Shader.Find("Standard"));eyeMaterial.color=new Color(.008f,.012f,.016f);AssetDatabase.CreateAsset(eyeMaterial,folder+"RayEyes.mat");}foreach(var skin in model.GetComponentsInChildren<Renderer>())if(skin.name.StartsWith("Eye")){skin.sharedMaterial=eyeMaterial;skin.transform.localScale*=1.8f;}
   var animation=model.GetComponent<Animation>();if(!animation)animation=model.AddComponent<Animation>();animation.AddClip(swim,"Swim");animation.clip=swim;animation.wrapMode=WrapMode.Loop;animation.playAutomatically=true;animation["Swim"].speed=.72f;
   var old=ray.GetComponent<MeshRenderer>();old.enabled=false;
   foreach(var skin in model.GetComponentsInChildren<SkinnedMeshRenderer>()){var baked=new Mesh();Bounds envelope=new Bounds();for(int sample=0;sample<12;sample++){animation.clip.SampleAnimation(model,animation.clip.length*sample/12);skin.BakeMesh(baked);if(sample==0)envelope=baked.bounds;else envelope.Encapsulate(baked.bounds);}float scale=Mathf.Max(.001f,(skin.rootBone?skin.rootBone.lossyScale.x:skin.transform.lossyScale.x));envelope.Expand(.3f);skin.localBounds=new Bounds(envelope.center/scale,envelope.size/scale);UnityEngine.Object.DestroyImmediate(baked);}animation.clip.SampleAnimation(model,0);
   var bounds=new Bounds();bool first=true;foreach(var r in model.GetComponentsInChildren<Renderer>()){if(first){bounds=r.bounds;first=false;}else bounds.Encapsulate(r.bounds);}Debug.Log("RAY_VISUAL_BOUNDS "+bounds+" root="+ray.transform.position+" scale="+ray.transform.localScale);
  }
  var octopus=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/UnderwaterArt/LicensedOctopus/Octopus.fbx");if(octopus){foreach(var r in octopus.GetComponentsInChildren<Renderer>())Debug.Log("OCTOPUS_IMPORT "+r.name+" "+r.bounds+" material="+r.sharedMaterial.name);}
 }
 public static void Capture(){EditorSceneManager.OpenScene(Scene);var camera=Camera.main;Directory.CreateDirectory("Renders");var ray=UnityEngine.Object.FindFirstObjectByType<StingraySwimmer>();var model=ray.transform.Find("Rigged stingray");if(model){var animation=model.GetComponent<Animation>();animation.clip.SampleAnimation(model.gameObject,.3f);}camera.transform.position=ray.transform.position+new Vector3(1.1f,1.5f,1.8f);camera.transform.LookAt(ray.transform.position);UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>().Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Polished_Stingray.png");
  var octopus=Array.Find(UnityEngine.Object.FindObjectsByType<ReefEncounter>(FindObjectsSortMode.None),a=>a.response==ReefEncounter.Response.Octopus);camera.transform.position=octopus.transform.position+new Vector3(1,.7f,1);camera.transform.LookAt(octopus.transform.position+Vector3.up*.12f);UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>().Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Polished_Octopus.png");
  var fish=Array.Find(UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None),a=>a.kind=="Lumen");camera.transform.position=fish.transform.position+fish.transform.right*.8f+Vector3.up*.15f+fish.transform.forward*.3f;camera.transform.LookAt(fish.transform.position);UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>().Apply(camera);ReefCorrectionAudit.Capture(camera,"Renders/Polished_Fish_Eyes.png");ReefDayFour.Capture();
 }
 public static void Validate(){ReefDayFour.Validate();EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var follower=UnityEngine.Object.FindFirstObjectByType<ReefFishFollower>();if(!follower)throw new Exception("Missing smooth companion");var home=follower.transform.position;float distance=0,maxTurn=0;for(int i=0;i<3600;i++){var before=follower.transform.position;var heading=follower.transform.forward;follower.Step(1f/30,home+new Vector3(Mathf.Sin(i/250f)*1.5f,0,Mathf.Cos(i/250f)*1.5f));distance+=Vector3.Distance(before,follower.transform.position);maxTurn=Mathf.Max(maxTurn,Vector3.Angle(heading,follower.transform.forward)*30);if(!follower.GetComponent<ReefSphereBody>().Clear(follower.transform.position))throw new Exception("Follower entered reef");}if(distance<5||maxTurn>40.1f)throw new Exception("Follower stalled or snapped "+distance+" "+maxTurn);
  Debug.Log("CREATURE_POLISH_VALIDATED followerDistance="+distance+" maxYawDegreesPerSecond="+maxTurn+" proximityVoices=4");Capture();
 }
 static void BakeDolphin(){const int rate=22050,seconds=7;using(var w=new BinaryWriter(File.Create("Assets/Ocean/Resources/DolphinNearby.wav"))){int n=rate*seconds;w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+n*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(n*2);double phase=0;for(int i=0;i<n;i++){double t=(double)i/rate,u=t-1.2;double value=0;if(u>0&&u<.8){phase+=2*Math.PI*(1700+1500*Math.Sin(u/.8*Math.PI))/rate;value=Math.Sin(phase)*Math.Pow(Math.Sin(u/.8*Math.PI),2)*.24;}double v=t-4.5;if(v>0&&v<.35)value+=Math.Sin(2*Math.PI*(2400*v+1200*v*v))*.16*Math.Pow(Math.Sin(v/.35*Math.PI),2);w.Write((short)(value*32767));}}AssetDatabase.Refresh();}
 public static void ValidateImportedRay(StingraySwimmer ray){var model=ray.transform.Find("Rigged stingray");if(!model)throw new Exception("Missing rigged ray");var animation=model.GetComponent<Animation>();var skin=Array.Find(model.GetComponentsInChildren<SkinnedMeshRenderer>(),r=>r.name=="Body");if(!animation||!animation.clip||!skin)throw new Exception("Ray rig or animation missing");animation.clip.SampleAnimation(model.gameObject,0);var a=new Mesh();skin.BakeMesh(a);animation.clip.SampleAnimation(model.gameObject,animation.clip.length*.4f);var b=new Mesh();skin.BakeMesh(b);float motion=0;var av=a.vertices;var bv=b.vertices;for(int i=0;i<av.Length;i++)motion=Mathf.Max(motion,Vector3.Distance(av[i],bv[i]));UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);if(motion<.02f||motion>3)throw new Exception("Ray swim deformation invalid "+motion);Debug.Log("RAY_RIG_VALIDATED vertices="+av.Length+" wingDisplacement="+motion);}
}
}
